def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue

            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))

            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)

            if maxr - minr < 2 or maxc - minc < 2:
                continue

            perimeter = all(
                grid[y][x] == color
                for y in range(minr, maxr + 1)
                for x in range(minc, maxc + 1)
                if y in (minr, maxr) or x in (minc, maxc)
            )
            if not perimeter:
                continue

            fill = 7 if (maxr - minr - 1) % 2 == 1 else 2
            for y in range(minr + 1, maxr):
                for x in range(minc + 1, maxc):
                    if grid[y][x] == background:
                        out[y][x] = fill

    return out
